<?= $this->extend('admin/layout') ?><?= $this->section('content') ?><section class="panel"><div class="panel-head"><div><h2>Website enquiries</h2><p>Messages submitted through the public contact form.</p></div></div><?php if (! $inquiries): ?><p>No enquiries yet.</p><?php else: ?><div class="inquiry-list"><?php foreach ($inquiries as $inquiry): ?><article class="inquiry"><div class="inquiry-meta"><div><h3><?= esc($inquiry['subject']) ?></h3><p><strong><?= esc($inquiry['name']) ?></strong> · <a href="mailto:<?= esc($inquiry['email']) ?>"><?= esc($inquiry['email']) ?></a><?= $inquiry['phone'] ? ' · ' . esc($inquiry['phone']) : '' ?></p></div><span class="pill"><?= esc($inquiry['status']) ?></span></div><p class="inquiry-message"><?= nl2br(esc($inquiry['message'])) ?></p><?php if ($inquiry['company']): ?><small>Company: <?= esc($inquiry['company']) ?></small><?php endif ?><footer><small><?= esc($inquiry['created_at']) ?></small><form method="post" action="<?= site_url('admin/inquiries/' . $inquiry['id'] . '/status') ?>"><?= csrf_field() ?><select name="status"><option value="new" <?= $inquiry['status'] === 'new' ? 'selected' : '' ?>>New</option><option value="read" <?= $inquiry['status'] === 'read' ? 'selected' : '' ?>>Read</option><option value="archived" <?= $inquiry['status'] === 'archived' ? 'selected' : '' ?>>Archived</option></select><button>Save</button></form></footer></article><?php endforeach ?></div><?php endif ?></section><?= $this->endSection() ?>
